var i=`infrastructure-as-code-iac`;var a=92;var r={en:[{id:`T092-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Infrastructure as Code (IaC)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Load balancing distributes requests or work across instances to improve utilization, capacity and availability.`},{id:`B`,text:`Fault tolerance lets a system continue delivering acceptable behavior when components fail.`},{id:`C`,text:`Recovery Point Objective (RPO) is the maximum acceptable data-loss window; Recovery Time Objective (RTO) is the target time to restore service after a disruption.`},{id:`D`,text:`IaC defines infrastructure resources in version-controlled declarations or programs.`}]},{id:`T092-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Infrastructure as Code (IaC)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Choose user-centric indicators such as successful booking confirmation rate or latency percentiles.`},{id:`B`,text:`Plan changes before applying them, use state and drift detection, separate environments, and keep secrets outside source.`},{id:`C`,text:`Define which failures to tolerate: instance crash, zone loss, timeout, bad data or dependency unavailability.`},{id:`D`,text:`Define traffic switching, readiness checks, compatibility between application versions and shared data, monitored error budgets and automatic abort criteria.`}]},{id:`T092-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A hotel SaaS can provision databases, networks and monitoring through reviewed IaC.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Feature flags may separately control exposure of new business behavior.`},{id:`B`,text:`A booking request can be traced through API, payment provider and database, while a metric counts failed confirmations and logs record sanitized error context for diagnosis.`},{id:`C`,text:`An Angular frontend and Node.js API pipeline runs type checks, tests, build and integration tests, then deploys tagged artifacts through staging to production with health checks.`},{id:`D`,text:`Recreating staging becomes routine rather than relying on undocumented manual console clicks.`}]},{id:`T092-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Infrastructure as Code (IaC)`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Autoscaling cannot compensate for serial bottlenecks or unbounded contention.`},{id:`B`,text:`Redundant replicas sharing one database or cloud zone may share the same failure mode.`},{id:`C`,text:`Stateful databases cannot be treated as disposable without data migration and backup plans.`},{id:`D`,text:`IaC is not automatically idempotent or safe: changing a resource property may destroy state.`}]},{id:`T092-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It improves repeatability, reviewability and recovery by making environment changes explicit.`}]}]},{id:`T092-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Infrastructure as Code means manually maintaining servers and documenting changes later.`}]}]},{id:`T092-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Protect state backends and review destructive plans; manual emergency changes can create drift.`}]}]},{id:`T092-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Infrastructure as Code (IaC)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Plan changes before applying them, use state and drift detection, separate environments, and keep secrets outside source.`},{id:`B`,text:`IaC defines infrastructure resources in version-controlled declarations or programs.`},{id:`C`,text:`Manual drift should be accepted rather than reconciled with declared infrastructure.`},{id:`D`,text:`RPO specifies how quickly a system must recover, while RTO specifies permissible data loss.`}]},{id:`T092-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Infrastructure as Code (IaC)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Infrastructure as Code means manually maintaining servers and documenting changes later.`},{id:`B`,text:`Recreating staging becomes routine rather than relying on undocumented manual console clicks.`},{id:`C`,text:`A fallback that silently returns incorrect prices is always preferable to failure.`},{id:`D`,text:`Protect state backends and review destructive plans; manual emergency changes can create drift.`}]},{id:`T092-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A hotel SaaS can provision databases, networks and monitoring through reviewed IaC.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to load-model a booking API, identify bottlenecks, recommend a scaling policy and specify database saturation safeguards.`},{id:`B`,text:`Ask an agent to model failures of mail, cache and database dependencies separately and define degraded behavior, recovery tests and observability.`},{id:`C`,text:`Ask an agent to design immutable release images for an API and compare rollback behavior when application code changes versus when a database migration changes.`},{id:`D`,text:`Ask an agent to draft isolated staging/production infrastructure with resource boundaries, encrypted state, access roles and a plan for destructive-change approval.`}]},{id:`T092-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`How will you detect that reality differs from the declared infrastructure model?`}]}]},{id:`T092-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A hotel SaaS can provision databases, networks and monitoring through reviewed IaC.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Infrastructure as Code (IaC)`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T092-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A hotel SaaS can provision databases, networks and monitoring through reviewed IaC.`,b:!0},{t:` — propose three checks for `},{t:`Infrastructure as Code (IaC)`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T092-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A hotel SaaS can provision databases, networks and monitoring through reviewed IaC.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T092-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Infrastructure as Code (IaC)`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A hotel SaaS can provision databases, networks and monitoring through reviewed IaC.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T092-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Інфраструктура як код (IaC)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Балансування розподіляє запити між інстансами задля кращого використання ресурсів, пропускної здатності та доступності.`},{id:`B`,text:`Відмовостійкість дозволяє системі продовжувати прийнятну роботу за відмови компонентів.`},{id:`C`,text:`RPO — максимально допустимий проміжок втрати даних; RTO — цільовий час повернення сервісу після аварії.`},{id:`D`,text:`IaC визначає інфраструктуру через версіоновані декларації чи програми.`}]},{id:`T092-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Інфраструктура як код (IaC)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Обирайте орієнтовані на користувача показники: успішність підтверджень або перцентилі затримки.`},{id:`B`,text:`Плануйте зміни до застосування, використовуйте state й пошук drift, ізолюйте середовища та тримайте секрети поза кодом.`},{id:`C`,text:`Визначте допустимі відмови: падіння інстансу, зони, timeout, некоректні дані чи недоступність залежності.`},{id:`D`,text:`Визначте перемикання трафіку, readiness, сумісність версій із даними, контроль error budget і критерії автоматичного припинення.`}]},{id:`T092-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Готельний SaaS може створювати БД, мережі й моніторинг через переглянутий IaC.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Feature flag може окремо керувати новою поведінкою.`},{id:`B`,text:`Запит бронювання відстежується через API, платіжний провайдер і БД; метрика рахує невдалі підтвердження, а лог зберігає очищений контекст помилки.`},{id:`C`,text:`Pipeline Angular і Node.js запускає перевірку типів, тести, build та інтеграційні тести, потім просуває позначені артефакти через staging у production з health checks.`},{id:`D`,text:`Повторне розгортання staging стає звичайною процедурою замість ручних кліків у консолі.`}]},{id:`T092-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Інфраструктура як код (IaC)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Автомасштабування не усуває послідовні вузькі місця й надмірну конкуренцію.`},{id:`B`,text:`Резервні репліки зі спільною БД чи зоною хмари можуть мати спільну точку відмови.`},{id:`C`,text:`БД зі станом не можна вважати одноразовими без міграцій і backup.`},{id:`D`,text:`IaC не є автоматично безпечним чи ідемпотентним: зміна властивості може знищити ресурс із даними.`}]},{id:`T092-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Це підвищує відтворюваність, контроль змін і відновлення середовищ.`}]}]},{id:`T092-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`IaC означає вручну налаштовувати сервери й згодом документувати зміни.`}]}]},{id:`T092-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Захищайте state, перевіряйте небезпечні плани та обробляйте drift після ручних втручань.`}]}]},{id:`T092-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Інфраструктура як код (IaC)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Плануйте зміни до застосування, використовуйте state й пошук drift, ізолюйте середовища та тримайте секрети поза кодом.`},{id:`B`,text:`IaC визначає інфраструктуру через версіоновані декларації чи програми.`},{id:`C`,text:`Ручний дрейф слід залишати без змін замість узгодження з IaC.`},{id:`D`,text:`RPO визначає швидкість відновлення, а RTO — припустиму втрату даних.`}]},{id:`T092-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Інфраструктура як код (IaC)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`IaC означає вручну налаштовувати сервери й згодом документувати зміни.`},{id:`B`,text:`Повторне розгортання staging стає звичайною процедурою замість ручних кліків у консолі.`},{id:`C`,text:`Fallback із непомітно хибними цінами завжди кращий за помилку.`},{id:`D`,text:`Захищайте state, перевіряйте небезпечні плани та обробляйте drift після ручних втручань.`}]},{id:`T092-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Готельний SaaS може створювати БД, мережі й моніторинг через переглянутий IaC.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента змоделювати навантаження API бронювань, знайти вузькі місця, вибрати політику масштабування й захист БД від перевантаження.`},{id:`B`,text:`Попросіть агента окремо змоделювати збої пошти, кешу й БД та визначити деградацію, тести відновлення й моніторинг.`},{id:`C`,text:`Попросіть агента спроєктувати незмінні релізні образи API та порівняти відкат коду з відкатом після міграції БД.`},{id:`D`,text:`Попросіть агента описати ізольовану інфраструктуру staging/production із межами ресурсів, шифрованим state, ролями та затвердженням небезпечних змін.`}]},{id:`T092-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Як визначити, що реальна інфраструктура розійшлася з декларативною моделлю?`}]}]},{id:`T092-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Готельний SaaS може створювати БД, мережі й моніторинг через переглянутий IaC.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Інфраструктура як код (IaC)`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T092-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Готельний SaaS може створювати БД, мережі й моніторинг через переглянутий IaC.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Інфраструктура як код (IaC)`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T092-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Готельний SaaS може створювати БД, мережі й моніторинг через переглянутий IaC.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T092-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Інфраструктура як код (IaC)`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Готельний SaaS може створювати БД, мережі й моніторинг через переглянутий IaC.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var n={slug:i,topicId:92,questions:r};export{n as default,r as questions,i as slug,a as topicId};